#[derive(Clone, Copy, Debug)]
pub(super) enum Expected {
    Null,
    Nan,
    Bits(u64),
}
use Expected::{Bits as B, Nan as N, Null as Z};

// Four integer widths have identical exactly representable input values.
// Decimal precision remains a real input axis; only its scale determines the
// binary64 conversion in these original small-i128 carrier declarations.
pub(super) fn peer_expectation_index(peer: usize) -> usize {
    match peer {
        0..=3 => 0,
        4 => 1,
        5 => 2,
        6..=157 => {
            let precision = (peer - 6) / 4 + 1;
            match (peer - 6) % 4 {
                0 => 3,
                1 => 4,
                2 => 5,
                _ => 5 + precision,
            }
        }
        _ => panic!("peer outside frozen full carrier/precision axis"),
    }
}
pub(super) fn complete(
    float: usize,
    peer: usize,
    reversed: bool,
    op: usize,
) -> &'static [Expected; 12] {
    &COMPLETE[float][peer_expectation_index(peer)][usize::from(reversed)][op]
}
pub(super) fn scalar(rhs: usize, reversed: bool, op: usize) -> &'static [Expected; 12] {
    &SCALARS[rhs][usize::from(reversed)][op]
}

